function loadChapterHeader(){const n=document.querySelector("header");if(!n)return;const s=window.location.pathname;let e="Class 9";s.includes("class-10")?e="Class 10":s.includes("class-11")?e="Class 11":s.includes("class-12")&&(e="Class 12");const t=s.includes("/sample-papers/"),l=t?"../../../":"../../../../",o=t?"../":"../../";n.innerHTML=`
        <a href="${l}" class="logo">
            <span style="font-size: 1.5em;">&int;</span> SJMaths
        </a>
        <div style="display: flex; align-items: center; gap: 10px;">
            <a href="${o}" class="nav-btn" style="font-size: 0.9rem; padding: 5px 15px;">
                <i class="fas fa-graduation-cap"></i> ${e}
            </a>
        </div>
    `;const a=document.querySelector("#darkToggle i");document.body.classList.contains("dark-mode")&&a&&(a.classList.remove("fa-moon"),a.classList.add("fa-sun"))}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",loadChapterHeader):loadChapterHeader();
